<?php
declare(strict_types=1);
function faculty_text($v,int $max,bool $required=false):string{if(!is_string($v)||mb_strlen(trim($v))>$max||($required&&trim($v)===''))throw new InvalidArgumentException('Check the required text and its length.');return trim($v);}
function faculty_profile(array $in):array{
 $d=[];foreach(['fullName'=>120,'designation'=>100,'phone'=>20,'email'=>160,'bloodGroup'=>4,'emergencyName'=>120,'emergencyPhone'=>20,'quote'=>400,'bio'=>1500,'photo'=>32] as $k=>$max)$d[$k]=faculty_text($in[$k]??'',$max,in_array($k,['fullName','designation'],true));
 foreach(['phone','emergencyPhone'] as $k)if($d[$k]!==''&&!preg_match('/^\+?[0-9 ()-]{10,20}$/',$d[$k]))throw new InvalidArgumentException('Use a valid contact number.');if($d['email']!==''&&!filter_var($d['email'],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Check the email address.');if(!in_array($d['bloodGroup'],['','A+','A-','B+','B-','AB+','AB-','O+','O-'],true))throw new InvalidArgumentException('Choose a blood group or leave it blank.');if($d['photo']!==''&&!preg_match('/^[a-f0-9]{32}$/',$d['photo']))throw new InvalidArgumentException('Choose an uploaded profile photo.');
 foreach(['degrees','subjects','superpowers'] as $k){$v=$in[$k]??[];if(!is_array($v)||!array_is_list($v)||count($v)>12)throw new InvalidArgumentException('Use up to twelve entries per list.');$d[$k]=array_values(array_unique(array_map(fn($x)=>faculty_text($x,100,true),$v)));}
 foreach(['shareParents','shareWebsite'] as $k)$d[$k]=($in[$k]??false)===true;return $d;
}
function faculty_public(array $p):array{return array_intersect_key($p,array_flip(['tid','fullName','designation','degrees','subjects','superpowers','quote','bio','photo','approvedAt']));}
function faculty_grid_errors(?array $grid,array $alloc):array{$errors=[];$seen=[];if(!$grid)return [];foreach($grid as $cls=>$days){if(!is_array($days)){$errors[]='Invalid timetable row.';continue;}foreach($days as $day=>$bells){if(!is_array($bells)){$errors[]='Invalid timetable day.';continue;}foreach($bells as $bell=>$index){if($index===-1)continue;if(!is_int($index)||!isset($alloc[$index])||($alloc[$index]['c']??'')!==(string)$cls){$errors[]='Timetable has a stale allocation.';continue;}$tid=(string)($alloc[$index]['t']??'');$key=$day.'|'.$bell.'|'.$tid;if(isset($seen[$key]))$errors[]='A teacher is assigned twice in one bell.';$seen[$key]=true;}}}return array_values(array_unique($errors));}
function faculty_metrics(string $tid,string $session,array $service,array $credentials):array{$verified=0.;$pending=0.;foreach($credentials as $c)if(($c['tid']??'')===$tid&&($c['session']??'')===$session&&($c['type']??'')==='CPD'){if(($c['status']??'')==='Verified')$verified+=(float)$c['hours'];elseif(($c['status']??'')==='Pending')$pending+=(float)$c['hours'];}$allow=$service['clAllowance']??null;$used=$service['clUsed']??null;return ['clBalance'=>is_numeric($allow)&&is_numeric($used)?max(0,(float)$allow-(float)$used):null,'clAllowance'=>$allow,'clUsed'=>$used,'clAsOf'=>$service['asOf']??null,'cpdVerified'=>$verified,'cpdPending'=>$pending,'cpdTarget'=>50,'biometricConnected'=>false,'onTimeStreak'=>null];}
function faculty_dir():string{$dir=dirname(__DIR__,2).'/school-private-faculty';if(!is_dir($dir)&&!mkdir($dir,0700,true)&&!is_dir($dir))throw new RuntimeException('Private photo storage unavailable');$real=realpath($dir);$root=realpath(dirname(__DIR__));if(!$real||($root&&str_starts_with($real,$root.DIRECTORY_SEPARATOR)))throw new RuntimeException('Private photo storage must be outside the website root');return $real;}
function faculty_id_lookup(string $token):?array{if(!preg_match('/^[a-f0-9]{48}$/',$token))return null;$id=sch_rec_get('facultyId',hash('sha256',$token));if(!$id||($id['revoked']??true)||($id['expires']??0)<time())return null;$approved=sch_rec_get('facultyApproved',(string)$id['tid']);$teacher=sch_rec_get('teacher',(string)$id['tid']);if(!$teacher||!$approved||($approved['version']??0)!==$id['version'])return null;return ['id'=>$id,'profile'=>$approved];}
function faculty_public_profiles(string $scope,?array $allowed=null):array{$out=[];foreach(learn_rows('facultyApproved') as $tid=>$p){$draft=sch_rec_get('facultyProfile',$tid);$flag=$scope==='website'?'shareWebsite':'shareParents';if(!$draft||empty($draft[$flag])||empty($p[$flag])||!sch_rec_get('teacher',$tid)||($allowed!==null&&!in_array($tid,$allowed,true)))continue;$public=faculty_public($p);$public['photoData']=faculty_photo_data((string)($p['photo']??''));$out[]=$public;}return $out;}

function faculty_photo_data(string $id):string{if(!preg_match('/^[a-f0-9]{32}$/',$id))return '';$m=sch_rec_get('facultyPhoto',$id);if(!$m)return '';$path=faculty_dir().'/'.$m['file'];return is_file($path)?'data:image/jpeg;base64,'.base64_encode(file_get_contents($path)):'';}
